/** Roles on a sheet, by user name. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/roles")
public class RoleController {

    /** A user name's assigned role as the screen shows it. */
    public record RoleView(String user, String role) {

        public static RoleView of(Role role) {
            return new RoleView(role.getUserName(), role.getRole());
        }
    }

    /** A role as the form submits it: clerk, steward or viewer. */
    public record RoleForm(@NotNull @Pattern(regexp = Role.CLERK + "|" + Role.STEWARD + "|" + Role.VIEWER) String role) {
    }

    private final RoleService roles;
    private final SheetHistory history;

    public RoleController(RoleService roles, SheetHistory history) {
        this.history = history;
        this.roles = roles;
    }

    @GetMapping
    public List<RoleView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.viewsAsOf(sheetId, asOf).roles();
        }
        return roles.list(sheetId).stream().map(RoleView::of).toList();
    }

    @PutMapping("/{userName}")
    public RoleView set(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S(.*\\S)?") String userName,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RoleForm request) {
        return RoleView.of(roles.set(sheetId, user, userName, request.role()));
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

/** The roles a sheet's settings can assign (a viewer sees everything and changes nothing); a name with none assigned is a clerk. */
export const ROLES = ['clerk', 'steward', 'viewer'] as const;
export type RoleName = (typeof ROLES)[number];

export interface RoleView {
  user: string;
  role: RoleName;
}

// The roles assigned to user names on the active sheet.
@Injectable({ providedIn: 'root' })
export class Roles {
  private readonly http = inject(HttpClient);
  private readonly list = signal<RoleView[]>([]);
  readonly all = this.list.asReadonly();

  /** Re-read a sheet's roles from the store; null clears them. */
  load(sheetId: string | null): Observable<RoleView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<RoleView[]>(this.base(sheetId)).pipe(tap((roles) => this.list.set(roles)));
  }

  /** Assign a role to a user name, replacing the one it had. */
  set(sheetId: string, user: string, role: RoleName): Observable<RoleView> {
    return this.http
      .put<RoleView>(`${this.base(sheetId)}/${encodeURIComponent(user)}`, { role })
      .pipe(
        tap((saved) =>
          this.list.update((list) =>
            [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => (a.user < b.user ? -1 : a.user > b.user ? 1 : 0)),
          ),
        ),
      );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/roles`;
  }
}
